SELECT * FROM oa_schedule_event WHERE tenant_id = #{tenantId} AND room_id = #{roomId}
AND 
AND start_time < #{end} AND DATE_ADD(end_time, INTERVAL buffer_minutes_snapshot MINUTE) > #{start}
FOR UPDATE

SELECT * FROM oa_schedule_event WHERE tenant_id = #{tenantId} AND room_id = #{roomId}
AND  AND end_time > #{now}
FOR UPDATE

SELECT * FROM oa_schedule_event WHERE tenant_id = #{tenantId} AND room_id = #{roomId}
AND 
AND start_time < #{end} AND DATE_ADD(end_time, INTERVAL buffer_minutes_snapshot MINUTE) > #{start}
ORDER BY start_time, event_id

SELECT meeting.* FROM oa_schedule_event meeting
WHERE meeting.tenant_id = #{tenantId} AND meeting.deleted = 0 AND meeting.recurrence_role != 'SERIES'
AND meeting.status IN ('PLANNED', 'IN_PROGRESS') AND meeting.approval_status NOT IN ('DRAFT', 'REJECTED', 'CANCELLED')
AND meeting.start_time < #{end} AND meeting.end_time > #{start}
AND meeting.event_id != #{excludeId}
AND (meeting.creator_id IN #{userId}
  OR EXISTS (SELECT 1 FROM oa_meeting_attendance invitation WHERE invitation.tenant_id = meeting.tenant_id
    AND invitation.schedule_event_id = meeting.event_id AND invitation.deleted = 0 AND invitation.acceptance_status != 'DECLINED'
    AND invitation.user_id IN #{userId}))
ORDER BY meeting.start_time, meeting.event_id

mapper.update:
UPDATE oa_meeting_attendance SET acceptance_status = #{invitation.acceptanceStatus}, response_time = #{invitation.responseTime},
    invitation_version = #{invitation.invitationVersion}, deleted = #{invitation.deleted}, update_by = #{invitation.updateBy}, update_time = #{invitation.updateTime}
WHERE tenant_id = #{invitation.tenantId} AND id = #{invitation.id} AND schedule_event_id = #{invitation.scheduleEventId} AND user_id = #{invitation.userId}

mapper.select:
SELECT event_id FROM oa_schedule_event WHERE tenant_id = #{tenantId} AND deleted = 0 AND event_id > #{afterId}
    AND recurrence_role != 'SERIES' AND status = 'PLANNED' AND approval_status = 'PENDING' AND end_time <= #{now}
ORDER BY event_id LIMIT 100
